import time
from .exceptions import AlarmPresentException, TimeoutError
from .rbts import ResourceBTS
from .pbts import FSM


class AlarmsEndpoint(object):
    FAULT_ID_KEY = 'additionalText1'
    ALARM_ID_KEY = 'specificProblem'

    @staticmethod
    def get_active_faults(session_handler, timeout=None):
        """
        Gets active faults from BTS.

        :return: list of active faults
        """
        return ResourceBTS(session_handler).get_faults(ResourceBTS.ALARM_STATE_ACTIVE, timeout=timeout)

    @staticmethod
    def get_active_alarms(session_handler, timeout=None):
        """
        Gets active alarms including faults from BTS and alarms from RCP.

        :return: list of active alarms
        """
        return ResourceBTS(session_handler).get_alarms(ResourceBTS.ALARM_STATE_ACTIVE, timeout=timeout)

    @staticmethod
    def get_historic_faults(session_handler, timeout=None):
        """
        Gets historic faults from BTS.

        :return: list of historic faults
        """
        return ResourceBTS(session_handler).get_faults(ResourceBTS.ALARM_STATE_HISTORY, timeout=timeout)

    @staticmethod
    def get_historic_alarms(session_handler, timeout=None):
        """
        Gets historic alarms including faults from BTS and alarms from RCP.

        :return: list of historic alarms
        """
        return ResourceBTS(session_handler).get_alarms(ResourceBTS.ALARM_STATE_HISTORY, timeout=timeout)

    @classmethod
    def wait_for_alarm(cls, session_handler, alarm, timeout=30):
        """
        Waits for given alarm to be reported by REST API.

        :param session_handler: session
        :param alarm: int - number of alarm
        :param timeout: int - max timeout in seconds to wait for alarm to appear until TimeoutError is raised
        """
        cls._wait_for_fault_or_alarm_state(
            session_handler, fault=alarm,
            get_faults_or_alarms=cls.get_active_alarms,
            extract_alarm_or_fault=cls._extract_alarm_id,
            timeout=timeout, is_fault_desired=lambda desired: desired)

    @classmethod
    def wait_for_fault(cls, session_handler, fault, source=None, timeout=30):
        """
        Waits for given fault to be reported in WebUI. If source was specified, then
        the keyword will wait for specific fault number AND specific fault source.

        :param session_handler: session
        :param fault: int - number of fault
        :param source: str - source of fault, note that gNB is skipped in the path
        :param timeout: int - max timeout in seconds to wait for fault to appear until TimeoutError is raised
        """
        return cls._wait_for_fault_or_alarm_state(
            session_handler, fault=fault,
            get_faults_or_alarms=cls.get_active_faults,
            source=source, extract_alarm_or_fault=cls._extract_fault_id,
            timeout=timeout, is_fault_desired=lambda desired: desired)

    @classmethod
    def wait_for_fault_to_disappear(cls, session_handler, fault, source=None,
                                    timeout=30):
        """
        Waits for given fault or alarm to disappear in WebUI.
        If source was specified, then the keyword will wait for specific
        fault number AND specific fault source.

        :param session_handler: session
        :param fault: int - number of fault
        :param source: str - source of fault, note that gNB is skipped in the path
        :param timeout: int - max timeout to wait in seconds for fault to disappear until TimeoutError is raised
        """
        return cls._wait_for_fault_or_alarm_state(
            session_handler, fault=fault,
            get_faults_or_alarms=cls.get_active_faults,
            source=source, extract_alarm_or_fault=cls._extract_fault_id,
            timeout=timeout, is_fault_desired=lambda desired: not desired)

    @classmethod
    def _wait_for_fault_or_alarm_state(cls,
                                       session_handler,
                                       get_faults_or_alarms,
                                       fault,
                                       is_fault_desired,
                                       extract_alarm_or_fault,
                                       source=None,
                                       timeout=30):

        def _fault_filter(f):
            is_wanted_fault = False
            try:
                is_wanted_fault = int(fault) == extract_alarm_or_fault(f)
            except KeyError:
                pass
            if source is not None:
                actual_source = f[ResourceBTS.FAULT_SOURCE].upper()
                return is_wanted_fault and source.upper() in actual_source
            else:
                return is_wanted_fault

        cls._wait_for_state(_fault_filter, get_faults_or_alarms,
                            is_fault_desired, session_handler, timeout)

    @classmethod
    def _wait_for_state(cls,
                        fault_filter,
                        get_faults_or_alarms,
                        is_fault_desired,
                        session_handler,
                        timeout):
        faults = get_faults_or_alarms(session_handler)
        is_fault_present = any(filter(fault_filter, faults))
        while not is_fault_desired(is_fault_present) and timeout > 0:
            timeout -= 1
            time.sleep(1)
            faults = get_faults_or_alarms(session_handler)
            is_fault_present = any(filter(fault_filter, faults))
        if timeout == 0 and not is_fault_desired(is_fault_present):
            raise TimeoutError

    @classmethod
    def wait_for_alarm_to_disappear(cls, session_handler, alarm, timeout=30):
        """
        Waits for given alarm to disappear in WebUI.

        :param session_handler: session
        :param alarm: int - alarm id or number
        :param timeout: int - max timeout to wait in seconds for alarm to disappear until TimeoutError is raised
        """
        return cls._wait_for_fault_or_alarm_state(
            session_handler, fault=alarm,
            get_faults_or_alarms=cls.get_active_alarms,
            extract_alarm_or_fault=cls._extract_alarm_id,
            timeout=timeout, is_fault_desired=lambda desired: not desired)

    @staticmethod
    def get_active_faults_number(session_handler, timeout=None):
        """
        Gets number of active faults in REST API.

        :return: number of active faults
        """
        return len(AlarmsEndpoint.get_active_faults(session_handler, timeout=timeout))

    @staticmethod
    def get_active_alarms_number(session_handler, timeout=None):
        """
        Gets number of active alarms including faults from BTS and RCP alarms in REST API.

        :return: number of active alarms
        """
        return len(AlarmsEndpoint.get_active_alarms(session_handler, timeout=timeout))

    @staticmethod
    def get_historic_faults_number(session_handler, timeout=None):
        """
        Gets number of historic faults in REST API.

        :return: number of historic faults
        """
        return len(AlarmsEndpoint.get_historic_faults(session_handler, timeout=timeout))

    @staticmethod
    def get_historic_alarms_number(session_handler, timeout=None):
        """
        Gets number of historic alarms including faults from BTS and RCP alarms in REST API.

        :return: number of historic alarms
        """
        return len(AlarmsEndpoint.get_historic_alarms(session_handler, timeout=timeout))

    @staticmethod
    def check_active_faults(session_handler, allow_negative_result=False, timeout=None):
        """
        Checks if any faults are reported by REST API.

        :param session_handler: session
        :param allow_negative_result: if True, then allow to pass even if faults are detected,
            otherwise raises AlarmPresentException if faults are detected,
            defaults to False
        :param timeout: (optional) Timeout for getting response, defaults to None (indefinite).
        """
        if not allow_negative_result and AlarmsEndpoint.get_active_faults_number(session_handler, timeout=timeout) != 0:
            raise AlarmPresentException

    @staticmethod
    def check_active_alarms(session_handler, allow_negative_result=False, timeout=None):
        """
        Checks if any alarms are reported by REST API.

        :param session_handler: session
        :param allow_negative_result: if True, then allow to pass even if alarms are detected,
            otherwise raises AlarmPresentException if alarms are detected,
            defaults to False
        :param timeout: (optional) Timeout for getting response, defaults to None (indefinite).
        """
        if not allow_negative_result and AlarmsEndpoint.get_active_alarms_number(session_handler, timeout=timeout) != 0:
            raise AlarmPresentException

    @staticmethod
    def check_historic_faults(session_handler, allow_negative_result=False, timeout=None):
        """
        Checks if any faults were reported by REST API.

        Note: this keyword is different than one in ta_selenium_megazone.
              In ta_selenium_megazone historic_faults contained also active faults.
              For active and historic faults use check_all_faults

        :param session_handler: session
        :param allow_negative_result: if True, then allow to pass even if faults are detected,
            otherwise raises AlarmPresentException if faults are detected,
            defaults to False
        :param timeout: (optional) Timeout for getting response, defaults to None (indefinite).
        """
        if not allow_negative_result and \
                AlarmsEndpoint.get_historic_faults_number(session_handler, timeout=timeout) != 0:
            raise AlarmPresentException

    @staticmethod
    def check_historic_alarms(session_handler, allow_negative_result=False, timeout=None):
        """
        Checks if any alarms were reported by REST API.

        :param session_handler: session
        :param allow_negative_result: if True, then allow to pass even if alarms are detected,
            otherwise raises AlarmPresentException if alarms are detected,
            defaults to False
        :param timeout: (optional) Timeout for getting response, defaults to None (indefinite).
        """
        if not allow_negative_result and \
                AlarmsEndpoint.get_historic_alarms_number(session_handler, timeout=timeout) != 0:
            raise AlarmPresentException

    @staticmethod
    def check_all_faults(session_handler, allow_negative_result=False, timeout=None):
        """
        Checks if any (active or historic) faults are reported by REST API.

        :param session_handler: session
        :param allow_negative_result: if True, then allow to pass even if faults are detected,
            otherwise raises AlarmPresentException if faults are detected,
            defaults to False
        :param timeout: (optional) Timeout for getting response, defaults to None (indefinite).
        """
        total_faults = (AlarmsEndpoint.get_active_faults_number(session_handler, timeout=timeout)
                        + AlarmsEndpoint.get_historic_faults_number(session_handler, timeout=timeout))
        if not allow_negative_result and total_faults != 0:
            raise AlarmPresentException

    @staticmethod
    def check_all_alarms(session_handler, allow_negative_result=False, timeout=None):
        """
        Checks if any (active or historic) alarms are reported by REST API.

        :param session_handler: session
        :param allow_negative_result: if True, then allow to pass even if alarms are detected,
            otherwise raises AlarmPresentException if alarms are detected,
            defaults to False
        :param timeout: (optional) Timeout for getting response, defaults to None (indefinite).
        """
        total_faults = (AlarmsEndpoint.get_active_alarms_number(session_handler, timeout=timeout)
                        + AlarmsEndpoint.get_historic_alarms_number(session_handler, timeout=timeout))
        if not allow_negative_result and total_faults != 0:
            raise AlarmPresentException

    @classmethod
    def check_faults_are_absent(cls, session_handler, fault_ids, timeout=None):
        """
        Checks if faults are absent in megazone.
        If faults exist then AlarmPresentException is raised.

        :param session_handler: session
        :param fault_ids: list of fault ids to check
        :param timeout: (optional) Timeout for getting response, defaults to None (indefinite).
        """
        undesired_ids = set(fault_ids)
        faults = cls.get_active_faults(session_handler, timeout=timeout)
        oam_faults = {cls._extract_fault_id(f): f for f in faults}
        faults = undesired_ids.intersection(oam_faults.keys())
        if len(faults) > 0:
            raise AlarmPresentException(faults, [oam_faults[f] for f in faults])

    @classmethod
    def _extract_fault_id(cls, fault):
        """Extracts fault id from fault."""
        txt = fault[cls.FAULT_ID_KEY]
        return int(txt.split()[0])

    @classmethod
    def _extract_alarm_id(cls, alarm):
        """
        Extracts alarm or fault id.
        :param id alarm or fault id
        """
        return int(alarm[cls.ALARM_ID_KEY])

    @staticmethod
    def _check_alarm_or_fault_is_absent(get_alarms_or_faults, extract_id,
                                        arg, type_id, timeout):
        """
        Common method to check  if alarm/fault is absent in megazone.
        If alarm/fault exists then Exception is raised.

        :param get_alarms_or_faults: input function for getting active alarms or active faults.
        :param extract_id: extracted alarm or fault id from active alarm or fault list.
        :param arg: argument for the above function get_alarms_or_faults
        :param type_id: expected alarm or fault id
        """
        present = get_alarms_or_faults(arg, timeout=timeout)
        for a in present:

            try:
                type_no = extract_id(a)
            except KeyError:
                return False
            if type_no == type_id:
                raise AlarmPresentException(a)

    @classmethod
    def check_fault_is_absent(cls, session_handler, fault_id, timeout):
        """
        Checks if fault is absent in megazone.
        If fault exists then AlarmPresentException is raised.

        :param session_handler: session
        :param fault_id: id of fault
        :param timeout: timeout in seconds
        """
        cls._check_alarm_or_fault_is_absent(
            cls.get_active_faults, cls._extract_fault_id,
            session_handler, fault_id, timeout=timeout)

    @classmethod
    def check_alarm_is_absent(cls, session_handler, alarm_id, timeout):
        """
        Checks if alarm is absent in megazone.
        If fault exists then AlarmPresentException is raised.

        :param session_handler: session
        :param alarm_id: id of alarm
        :param timeout: timeout in seconds
        """
        cls._check_alarm_or_fault_is_absent(
            cls.get_active_alarms, cls._extract_alarm_id,
            session_handler, alarm_id, timeout=timeout)

    @staticmethod
    def trigger_fault_5g_bts_configuration_failed(session_handler, fsm_id, timeout):
        """
        It triggers 6293 fault in classical testline.

        :param session_handler:(optional) Session to use, can be an alias or
                        SessionHandler object.
        :param str fsm_id: id of system module. Default equals '1'.
        :param timeout: (optional) Timeout for getting response, defaults to None (indefinite).
        """
        return FSM(session_handler).trigger_fault_5g_bts_configuration_failed(fsm_id, timeout=timeout)
